package com.stepflow.app;
import android.app.*;import android.content.*;import android.hardware.*;import android.os.IBinder;
/** Maintains a low-frequency foreground sensor listener; the hardware also counts independently. */
public class StepTrackingService extends Service implements SensorEventListener {static final String CHANNEL="stepflow_tracking";SensorManager manager;Sensor sensor;SharedPreferences prefs;@Override public void onCreate(){super.onCreate();prefs=getSharedPreferences("stepflow",MODE_PRIVATE);NotificationChannel c=new NotificationChannel(CHANNEL,"Schrittzähler",NotificationManager.IMPORTANCE_LOW);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(c);startForeground(7,new Notification.Builder(this,CHANNEL).setSmallIcon(R.drawable.ic_stepflow_notification).setContentTitle("StepFlow ist aktiv").setContentText("Schritte für heute werden erfasst.").setOngoing(true).build());manager=(SensorManager)getSystemService(SENSOR_SERVICE);sensor=manager.getDefaultSensor(Sensor.TYPE_STEP_COUNTER);if(sensor!=null)manager.registerListener(this,sensor,SensorManager.SENSOR_DELAY_NORMAL);}@Override public void onSensorChanged(SensorEvent e){long total=(long)e.values[0];String today=MainActivity.dayKey(),day=prefs.getString("day","");long saved=prefs.getLong("daily_steps",0),last=prefs.getLong("last_sensor",-1);if(!today.equals(day)){saved=0;last=total;}else if(last<0)last=total;else if(total>=last)saved+=total-last;prefs.edit().putString("day",today).putLong("daily_steps",saved).putLong("last_sensor",total).apply();}@Override public void onAccuracyChanged(Sensor s,int a){}@Override public IBinder onBind(Intent i){return null;}@Override public void onDestroy(){if(manager!=null)manager.unregisterListener(this);super.onDestroy();}}
